<div class="card"><div class="card-header"><a href="<?= site_url('admin/pengguna/tambah') ?>" class="btn btn-primary"><i class="fas fa-plus"></i> Tambah Pengguna</a></div><div class="card-body table-responsive"><table class="table table-bordered table-striped datatable"><thead><tr><th>No</th><th>Nama</th><th>Username</th><th>Role</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($users as $i=>$u): ?><tr><td><?= $i+1 ?></td><td><?= html_escape($u->nama) ?></td><td><?= html_escape($u->username) ?></td><td><span class="badge badge-info"><?= html_escape(ucfirst($u->role)) ?></span></td><td><?= $u->is_active ? '<span class="badge badge-success">Aktif</span>' : '<span class="badge badge-secondary">Nonaktif</span>' ?></td><td><a class="btn btn-sm btn-warning" href="<?= site_url('admin/pengguna/edit/'.$u->id) ?>"><i class="fas fa-edit"></i></a> <?= form_open('admin/pengguna/hapus/'.$u->id, array('class'=>'d-inline','onsubmit'=>"return confirm('Hapus pengguna ini?')")) ?><button class="btn btn-sm btn-danger"><i class="fas fa-trash"></i></button><?= form_close() ?></td></tr><?php endforeach; ?></tbody></table></div></div>
